<?php
function upgrade(PDO $db): void {
$db->exec("CREATE TABLE IF NOT EXISTS expenses(id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,category VARCHAR(100) NOT NULL,amount DECIMAL(12,2) NOT NULL,per_person BOOLEAN NOT NULL DEFAULT 0,FOREIGN KEY(trip_id) REFERENCES trips(id))");
$db->exec("CREATE TABLE IF NOT EXISTS audit_log(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,event VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$db->exec("CREATE TABLE IF NOT EXISTS announcements(id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(trip_id) REFERENCES trips(id))");
$db->exec("CREATE TABLE IF NOT EXISTS packing(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,item VARCHAR(255) NOT NULL,done BOOLEAN NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id))");
}
